-- Matérias do mural anterior importadas como rascunhos para revisão editorial.
INSERT IGNORE INTO noticias (id_noticia,categoria,titulo,resumo,corpo,destaque) VALUES
(1,'Parcerias','CineAstra firma parceria com o Parque Linear de São Caetano do Sul','Acordo vai levar cinema, cultura e lazer para dentro do parque, aproximando a telona de quem vive e frequenta a cidade.','O CineAstra anuncia uma parceria com o Parque Linear de São Caetano do Sul. A iniciativa nasce com o objetivo de levar atividades de cinema e cultura para um dos espaços de convivência da cidade.

A primeira ação conjunta será a exibição ao ar livre de Vingadores: Doomsday, aberta à comunidade. Novas atividades poderão ser anunciadas conforme a parceria avançar.

Acompanhe este mural: todas as novidades, mudanças de programação e orientações ao público serão publicadas aqui em primeira mão.',0),
(2,'Transmissões','Vingadores: Doomsday será exibido ao ar livre no parque','Sessão especial no Parque Linear de São Caetano do Sul. Leve cadeira, manta e a vizinhança toda.','A transmissão de Vingadores: Doomsday acontecerá no Parque Linear de São Caetano do Sul, com tela montada ao ar livre e a estrutura de som do CineAstra.

Os portões abrem às 18:00 e a sessão começa às 19:30. Entrada: gratuita. Recomendamos chegar com antecedência para escolher bem o lugar no gramado.

Haverá bomboniere no local, com pipoca e bebidas. Em caso de chuva ou qualquer mudança, o novo plano será divulgado neste mural e nas redes do CineAstra.',1),
(3,'Parcerias','CineAstra conversa com teatros e cinemas da região','Objetivo é montar uma rede cultural local, com programação conjunta e benefícios entre parceiros.','Além do Parque Linear, o CineAstra está em conversas com teatros e cinemas da região para formar uma rede cultural integrada.

A ideia é compartilhar programação, criar sessões especiais e oferecer vantagens ao público que circula entre os espaços parceiros.

Os nomes serão divulgados assim que as parcerias forem confirmadas.',0),
(4,'Avisos','Guia do público: o que levar e o que esperar da sessão ao ar livre','Chegada, bomboniere, clima e acessibilidade: tudo o que você precisa saber antes de ir.','Leve cadeira de praia, manta ou almofada e, se quiser, um agasalho: à noite a temperatura costuma cair.

A bomboniere do CineAstra estará no local. Confira as orientações do parque sobre alimentos e bebidas trazidos de casa.

Dúvidas sobre acessibilidade ou acesso ao local? Fale com a gente pelo cadastro de avisos no fim da página.',0),
(5,'Comunidade','Seu bairro, sua sessão: indique filmes para as próximas exibições','Queremos ouvir a comunidade para escolher os próximos títulos e locais.','O CineAstra quer que a programação ao ar livre reflita o que a comunidade gosta de assistir.

Envie sua sugestão de filme ou de local pelo cadastro de contato no fim da página. As ideias mais pedidas entram na curadoria das próximas sessões.',0);
